-- ----------------------------------------------------------------
-- MaNGOS transactional update
-- ----------------------------------------------------------------
SET NAMES utf8;
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE='';

-- ----------------------------------------------------------------
-- This is an attempt to create a full transactional MaNGOS update
-- Now compatible with newer MySql Databases (v1.5)
-- ----------------------------------------------------------------
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

-- CREATE DEFINER=`root`@`localhost` PROCEDURE `update_mangos`()
CREATE PROCEDURE `update_mangos`()
BEGIN
    DECLARE bRollback BOOL  DEFAULT FALSE ;
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET `bRollback` = TRUE;

    -- Current Values (TODO - must be a better way to do this)
    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `STRUCTURE` DESC, `CONTENT` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `STRUCTURE` DESC, `CONTENT` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `STRUCTURE` DESC, `CONTENT` DESC LIMIT 0,1);

    -- Expected Values
    SET @cOldVersion = '23';
    SET @cOldStructure = '01';
    SET @cOldContent = '005';

    -- New Values
    SET @cNewVersion = '23';
    SET @cNewStructure = '01';
    SET @cNewContent = '006';
                            -- DESCRIPTION IS 30 Characters MAX
    SET @cNewDescription = 'mop_creatures';

                        -- COMMENT is 150 Characters MAX
    SET @cNewComment = 'Full SkyFire MoP creature conversion: templates, spawns, addons, equipment, classlevelstats and model info';

    -- Evaluate all settings
    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `STRUCTURE` DESC, `CONTENT` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version`=@cOldVersion AND `structure`=@cOldStructure AND `content`=@cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version`=@cNewVersion AND `structure`=@cNewStructure AND `content`=@cNewContent);

    IF (@cCurResult = @cOldResult) THEN    -- Does the current version match the expected version
        -- APPLY UPDATE
        START TRANSACTION;
        -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -
        -- -- PLACE UPDATE SQL BELOW -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --
        -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -

-- ============================================================================
-- Skyfire -> Mangos4 conversion, phase 1: CREATURES (wipe & clean re-import)
-- Generated from Skyfire.sql / Mangos4.sql dumps of 2026-07-26.
-- Target database: mangos4
--
-- What this does:
--   1. Deletes every creature spawn from the previous (broken) Skyfire import:
--      all rows on MoP maps [860, 870, 959, 960, 961, 962, 996, 1136] plus all rows with curhealth=0
--      (verified: every such row matches a Skyfire spawn guid+id+map).
--   2. Deletes the 0 zero-health creature_templates from that import.
--   3. Re-imports 10510 creature_templates with correct explicit
--      health/mana/armor (Expansion=-1 convention, values computed from
--      Skyfire creature_classlevelstats * per-creature multipliers).
--   4. Re-imports 36276 spawns on MoP maps with fresh guids
--      (8500000+), correct curhealth/curmana, phaseMask=1.
--   5. Rebuilds creature_addon / creature_template_addon / equip / onkill rep.
--
-- Safe to re-run (idempotent). Original Cataclysm content is not touched.
-- Apply with:  mysql -h 192.168.1.6 -u root -p mangos4 < 01_creatures.sql
-- ============================================================================

-- ---------------------------------------------------------------- 1. WIPE
DELETE FROM `creature` WHERE `map` IN (860,870,959,960,961,962,996,1136);
DELETE FROM `creature` WHERE `curhealth`=0;
DELETE FROM `creature` WHERE `guid` BETWEEN 8500000 AND 8599999;
